:root {
  color-scheme: dark;
  --ink: #17252d;
  --paper: #fff2cf;
  --gold: #f6bd50;
  --teal: #5bd1bd;
  --coral: #f47d68;
}

* { box-sizing: border-box; }
body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #18343b;
  background-image: radial-gradient(#28515a 1.5px, transparent 1.5px);
  background-size: 18px 18px;
  color: var(--ink);
  font: 16px/1.45 system-ui, sans-serif;
}
button { font: inherit; }
.board {
  width: min(100%, 940px);
  padding: clamp(20px, 5vw, 44px);
  background: var(--paper);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--gold), 12px 12px 0 var(--ink);
}
.heading { text-align: center; margin-bottom: 28px; }
.eyebrow { margin: 0 0 6px; color: #477169; font-weight: 800; letter-spacing: .16em; font-size: 14px; }
h1 { margin: 0; font-size: clamp(32px, 7vw, 52px); line-height: 1.1; letter-spacing: -.04em; }
.subtitle { margin: 10px 0 0; color: #53656a; }
.score-area { border: 3px solid var(--ink); background: #fff9e9; }
.frames { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); }
.frame { min-width: 0; min-height: 112px; border-right: 2px solid var(--ink); border-bottom: 2px solid var(--ink); }
.frame:last-child { border-right: 0; }
.frame-number { display: block; padding: 4px 2px; background: var(--teal); border-bottom: 2px solid var(--ink); text-align: center; font-weight: 800; font-size: 14px; }
.rolls { height: 38px; display: flex; justify-content: flex-end; align-items: center; border-bottom: 1px solid #c9c5b4; }
.roll { min-width: 23px; padding: 4px 2px; text-align: center; font-weight: 750; }
.roll + .roll { border-left: 1px solid #c9c5b4; }
.frame-score { display: grid; place-items: center; min-height: 38px; font-size: 20px; font-weight: 850; }
.total-panel { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: var(--ink); color: var(--paper); letter-spacing: .08em; font-weight: 800; }
.total-panel strong { color: var(--gold); font-size: 24px; letter-spacing: 0; }
.controls { margin-top: 28px; }
.control-heading { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-bottom: 12px; }
h2 { margin: 0; font-size: 20px; }
#turn-status { color: #477169; font-weight: 750; }
.pin-buttons { display: grid; grid-template-columns: repeat(11, minmax(0, 1fr)); gap: 8px; }
.pin-button, .reset-button { min-height: 48px; border: 3px solid var(--ink); color: var(--ink); background: var(--gold); font-weight: 850; cursor: pointer; box-shadow: 3px 3px 0 var(--ink); transition: transform .08s, box-shadow .08s, background .12s; }
.pin-button:hover, .reset-button:hover { background: var(--teal); }
.pin-button:active, .reset-button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
button:focus-visible { outline: 4px solid var(--coral); outline-offset: 3px; }
.pin-button:disabled { opacity: .4; cursor: not-allowed; box-shadow: none; }
.reset-button { margin-top: 18px; padding: 9px 16px; background: var(--coral); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 650px) {
  body { padding: 18px 12px; }
  .board { padding: 20px 14px; box-shadow: 5px 5px 0 var(--gold), 8px 8px 0 var(--ink); }
  .frames { grid-template-columns: repeat(5, minmax(0, 1fr)); }
  .frame:nth-child(5n) { border-right: 0; }
  .frame:nth-child(n+6) { border-bottom: 0; }
  .pin-buttons { grid-template-columns: repeat(6, minmax(0, 1fr)); }
}
@media (max-width: 390px) {
  .frame { min-height: 102px; }
  .frame-number { font-size: 13px; }
  .roll { min-width: 19px; }
  .pin-buttons { gap: 7px; }
}

const framesEl = document.querySelector('#frames');
const buttonsEl = document.querySelector('#pin-buttons');
const finalEl = document.querySelector('#final-score');
const statusEl = document.querySelector('#turn-status');
const announcementEl = document.querySelector('#announcement');
let rolls = [];

function scoreFrames() {
  const frames = [];
  let i = 0;
  let cumulative = 0;
  for (let frame = 0; frame < 10; frame++) {
    let score;
    let displayRolls;
    if (frame < 9) {
      const first = rolls[i];
      if (first === undefined) { frames.push({ rolls: [], total: null }); continue; }
      if (first === 10) {
        displayRolls = [10];
        if (rolls[i + 1] !== undefined && rolls[i + 2] !== undefined) score = 10 + rolls[i + 1] + rolls[i + 2];
        i++;
      } else if (rolls[i + 1] === undefined) {
        displayRolls = [first];
      } else {
        const second = rolls[i + 1];
        displayRolls = [first, second];
        if (first + second === 10) {
          if (rolls[i + 2] !== undefined) score = 10 + rolls[i + 2];
        } else score = first + second;
        i += 2;
      }
    } else {
      displayRolls = rolls.slice(i, i + 3);
      if (displayRolls.length === 3) score = displayRolls.reduce((a, b) => a + b, 0);
    }
    if (score === undefined) frames.push({ rolls: displayRolls, total: null });
    else { cumulative += score; frames.push({ rolls: displayRolls, total: cumulative }); }
  }
  return frames;
}

function isComplete() {
  const frames = scoreFrames();
  return frames[9]?.total !== null && frames[9]?.rolls.length >= 2 &&
    (frames[9].rolls[0] + frames[9].rolls[1] < 10 || frames[9].rolls.length === 3);
}

function framesFromRolls() {
  const frames = [];
  let i = 0;
  for (let frame = 0; frame < 9; frame++) {
    const first = rolls[i];
    if (first === undefined) { frames.push({ rolls: [] }); continue; }
    if (first === 10) {
      frames.push({ rolls: [10] });
      i++;
    } else if (rolls[i + 1] === undefined) {
      frames.push({ rolls: [first] });
    } else {
      frames.push({ rolls: [first, rolls[i + 1]] });
      i += 2;
    }
  }
  frames.push({ rolls: rolls.slice(i, i + 3) });
  return frames;
}

function tenthRollLimit() {
  const tenth = framesFromRolls()[9].rolls;
  if (tenth.length === 0) return 10;
  if (tenth.length === 1) return tenth[0] === 10 ? 10 : 10 - tenth[0];
  if (tenth.length === 2) {
    if (tenth[0] === 10 || tenth[0] + tenth[1] === 10) return 10;
    return 0;
  }
  return 0;
}

function markFor(frame, position, frameIndex) {
  const values = frame.rolls;
  const value = values[position];
  if (value === undefined) return '';
  if (frameIndex < 9) {
    if (position === 0 && value === 10) return 'X';
    if (position === 1 && values[0] + value === 10) return '/';
  } else {
    if (position === 0 && value === 10) return 'X';
    if (position === 1 && values[0] !== 10 && values[0] + value === 10) return '/';
    if (position === 1 && values[0] === 10 && value === 10) return 'X';
    if (position === 2) {
      if (value === 10) return 'X';
      const base = values[0] === 10 ? values[1] : values[0];
      if (base !== undefined && base < 10 && base + value === 10) return '/';
    }
  }
  return value === 0 ? '–' : String(value);
}

function render() {
  const scored = scoreFrames();
  framesEl.replaceChildren();
  scored.forEach((frame, index) => {
    const cell = document.createElement('div');
    cell.className = 'frame';
    const label = document.createElement('span');
    label.className = 'frame-number';
    label.textContent = `FRAME ${index + 1}`;
    const rollsRow = document.createElement('div');
    rollsRow.className = 'rolls';
    const slots = index === 9 ? 3 : 2;
    for (let pos = 0; pos < slots; pos++) {
      const mark = document.createElement('span');
      mark.className = 'roll';
      mark.textContent = markFor(frame, pos, index);
      rollsRow.append(mark);
    }
    const total = document.createElement('div');
    total.className = 'frame-score';
    total.textContent = frame.total === null ? '' : frame.total;
    cell.append(label, rollsRow, total);
    framesEl.append(cell);
  });
  const complete = isComplete();
  finalEl.textContent = complete ? scored[9].total : '—';
  const f = framesFromRolls();
  const current = f.findIndex((frame, idx) => idx < 9 && frame.rolls.length < (frame.rolls[0] === 10 ? 1 : 2));
  statusEl.textContent = current >= 0 ? `Frame ${current + 1} · Roll ${f[current].rolls.length + 1}` : `Frame 10 · Roll ${Math.max(1, f[9].rolls.length + 1)}`;
  const limit = (() => {
    const openFrame = f.slice(0, 9).findIndex((frame) => frame.rolls.length > 0 && frame.rolls.length < 2);
    if (openFrame >= 0) return 10 - f[openFrame].rolls[0];
    if (f.slice(0, 9).some((frame) => frame.rolls.length === 0)) return 10;
    return tenthRollLimit();
  })();
  buttonsEl.querySelectorAll('button').forEach((button) => {
    button.disabled = complete || Number(button.dataset.pins) > limit;
  });
}

for (let pins = 0; pins <= 10; pins++) {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'pin-button';
  button.dataset.pins = pins;
  button.textContent = pins;
  button.setAttribute('aria-label', `${pins} ${pins === 1 ? 'pin' : 'pins'} knocked down`);
  button.addEventListener('click', () => {
    const value = Number(button.dataset.pins);
    rolls.push(value);
    render();
    announcementEl.textContent = `Recorded ${value} ${value === 1 ? 'pin' : 'pins'}.`;
  });
  buttonsEl.append(button);
}

document.querySelector('#reset').addEventListener('click', () => {
  rolls = [];
  announcementEl.textContent = 'New game started.';
  render();
});
render();
